    armR.shoulder.rotation.set( 0.4, 0, 1.45);
    armR.forearmRot.rotation.set(0, 0, 1.30);
  }
  setGuardPose();

  // â”€â”€â”€ Stun stars (hidden until triggered) â”€â”€â”€
  const stunGroup = new THREE.Group();
  stunGroup.position.y = 2.15;
  stunGroup.visible = false;
  torso.add(stunGroup);
  const starColors = [0xfff44a, 0xffd700, 0xffe066];
  const stars = [];
  for (let i = 0; i < 3; i++){
    const s = new THREE.Mesh(
      new THREE.SphereGeometry(0.045, 8, 6),
      new THREE.MeshBasicMaterial({ color: starColors[i] })
    );
    stars.push(s);
    stunGroup.add(s);
  }

  // Shadow
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.5, 18),
    new THREE.MeshBasicMaterial({ color: 0x000, transparent: true, opacity: 0.55 })
  );
  shadow.rotation.x = -Math.PI/2;
  shadow.position.y = 0.012;
  root.add(shadow);

  return {
    root, torso, headGroup, neck, chest,
    armL, armR, legL, legR,
    legLKnee: legLData.kneeGroup,
    legRKnee: legRData.kneeGroup,
    setGuardPose,
    stunGroup, stars,
  };
}

// Generic per-arm pose helper.
function setArmPose(armSide, pose){
  if (pose.shoulderRot) armSide.shoulder.rotation.set(pose.shoulderRot[0], pose.shoulderRot[1], pose.shoulderRot[2]);
  if (pose.forearmRot)  armSide.forearmRot.rotation.set(pose.forearmRot[0], pose.forearmRot[1], pose.forearmRot[2]);
  if (pose.offset)      armSide.shoulder.position.set(pose.offset[0], pose.offset[1], pose.offset[2]);
}

