// Drive an arm by punch family + phase (0..3).
function animatePunch(b, kind, phase){
  const r = b.rig;
  const arm = (b.activeArm === 'lead') ? r.armL : r.armR;
  const otherArm = (b.activeArm === 'lead') ? r.armR : r.armL;
  // Other arm stays in guard (already set by setGuardPose above).
  const sign = (b.activeArm === 'lead') ? -1 : 1; // L arm = -z, R arm = +z

  // ext: 0 fully retracted, 1 fully extended.  Built from phase.
  const ext = (phase < 1) ? (phase * 0.25) :
              (phase < 2) ? (0.25 + 0.75 * (phase - 1)) :
              Math.max(0, 1 - (phase - 2));

  // Default starting rotations (each punch overrides).
  let shoulderX = -0.4 + sign * 0.0;
  let shoulderY = 0;
  let shoulderZ = 1.45;
  let forearmX  = 0;
  let forearmY  = 0;
  let forearmZ  = 1.30;

  switch (kind){
    case 'jab':
    case 'straight':
    case 'cross': {
      // Straight punch â€” shoulder swings forward (around Y), forearm extends.
      shoulderZ = 1.45 - ext * 1.45;          // arm comes down/out
      shoulderY = -sign * (0.2 + ext * 0.7);  // rotate arm forward
      shoulderX = -0.4 + ext * 0.55;
      forearmZ  = 1.30 - ext * 1.20;
      break;
    }
    case 'hook':
    case 'checkHook': {
      // Hook â€” arm parallel to ground, swings around Y.
      shoulderZ = 1.45 - ext * 0.85;
      shoulderY = -sign * (0.6 + ext * 1.4);
      shoulderX = -0.2 + ext * 0.4;
      forearmZ  = 1.30 - ext * 0.55;
      break;
    }
    case 'uppercut': {
      shoulderZ = 1.45 - ext * 1.65;          // drive up
      shoulderX = -0.7 + ext * 1.0;
      shoulderY = -sign * (0.1 + ext * 0.4);
      forearmZ  = 1.30 - ext * 0.95;
      forearmX  = ext * 0.3;
      break;
    }
