// Generic per-arm pose helper â€” drives all 4 joints.

function animatePunch(b, kind, phase){
  const r = b.rig;
  const arm = (b.activeArm === 'lead') ? r.armL : r.armR;
  const sign = (b.activeArm === 'lead') ? -1 : 1; // L = -z side, R = +z

  // ext: 0 retracted â†’ 1 fully extended. Slow wind-up, fast snap, slow recover.
  const ext = (phase < 1) ? (phase * 0.25) :
              (phase < 2) ? (0.25 + 0.75 * (phase - 1)) :
              Math.max(0, 1 - (phase - 2));

  // Defaults match guard pose â€” each case overrides relevant axes.
  let sX = (sign > 0) ? 0.25 : -0.30,  sY = 0,  sZ = (sign > 0) ? 1.40 : 1.35;
  let eZ = (sign > 0) ? 1.20 : 1.05;  // elbow HINGE (Z only)
  let pY = -0.28;                       // forearm PIVOT (Y only, -=supinated)
  let wX = 0.09, wZ = 0;               // wrist CONDYLOID (X+Z only)

  switch (kind){
    case 'jab':
    case 'straight': {
      // Lead-hand linear extension: shoulder forward, elbow straightens, forearm pronates at impact
      sZ = 1.35 - ext * 1.35;                   // shoulder abduction â†’ neutral
      sY = -sign * (0.18 + ext * 0.65);          // arm rotates forward toward opponent
      sX = (sign > 0 ? 0.25 : -0.30) + ext * 0.55;
      eZ = 1.05 - ext * 0.98;                   // HINGE: extends from ~60Â° to ~4Â°
      pY = -0.28 + ext * 1.55;                  // PIVOT: supinated guard â†’ full pronation at impact
      wX = 0.09;
      wZ = -ext * 0.10;                          // slight radial deviation at impact
      break;
    }
    case 'cross': {
      // Rear hand: hip+spine drives first (handled in animateBoxer), arm extends
      sZ = 1.40 - ext * 1.38;
      sY = -sign * (0.18 + ext * 0.72);
      sX = (sign > 0 ? 0.25 : -0.30) + ext * 0.60;
      eZ = 1.20 - ext * 1.15;                   // HINGE: rear arm starts more bent
      pY = -0.28 + ext * 1.65;                  // full pronation
      wX = 0.09;
      wZ = -ext * 0.08;
      break;
    }
    case 'hook':
    case 'checkHook': {
      // Shoulder horizontal adduction; ELBOW STAYS BENT (never fully extends = anatomically correct)
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 0.80;
      sY = -sign * (0.55 + ext * 1.38);          // big Y swing = horizontal adduction
      sX = (sign > 0 ? 0.25 : -0.30) + ext * 0.35;
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 0.22; // HINGE: stays ~80Â°+, hook never straightens
      pY = -0.28 + ext * 0.45;                  // partial pronation, palm ~45Â° at impact
      wX = -0.10 * ext;                          // slight wrist extension (knuckles drive)
      wZ = sign * ext * 0.08;                    // mild ulnar deviation
      break;
    }
    case 'uppercut': {
      // Elbow flexes MORE (increases Z), forearm supinates (palm faces fighter = anatomically correct)
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 1.62; // shoulder drives up hard
      sX = (sign > 0 ? 0.25 : -0.30) - 0.45 + ext * 1.00;
      sY = -sign * (0.10 + ext * 0.38);
      eZ = (sign > 0 ? 1.20 : 1.05) + ext * 0.42; // HINGE: MORE bent = drives up
      pY = -0.28 - ext * 0.68;                  // PIVOT: MORE supinated (palm toward fighter) âœ“
      wX = -0.20 * ext;                          // wrist extends slightly
      wZ = 0;
      break;
    }
    case 'overhand': {
      // Arc over the top: shoulder externally rotates then crashes down
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 1.02;
      sY = -sign * (0.38 + ext * 0.95);
      sX = (sign > 0 ? 0.25 : -0.30) - 0.65 + ext * 0.55;
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 0.55; // arm straightens partially mid-arc
      pY = -0.28 + ext * 1.20;                  // pronates through the arc
      wX = 0;
      wZ = -ext * 0.06;
      break;
    }
    case 'bodyShot': {
      // Shoulder drops, lumbar side-bends (handled in animateBoxer spineScale)
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 0.90;
      sY = -sign * (0.28 + ext * 0.65);
      sX = (sign > 0 ? 0.25 : -0.30) - ext * 0.22; // shoulder drives DOWN
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 0.60;
      pY = -0.28 + ext * 1.10;
      wX = 0.15 * ext;                           // slight flexion drives knuckles into ribs
      wZ = 0;
      break;
    }
    case 'liverShot': {
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 0.92;
      sY = -sign * (0.18 + ext * 0.58);
      sX = (sign > 0 ? 0.25 : -0.30) - ext * 0.28;
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 0.65;
      pY = -0.28 + ext * 1.15;
      wX = 0.12 * ext;
      wZ = sign * ext * 0.10; // ulnar deviation drives into liver
      break;
    }
    case 'shovelHook': {
      // Mid-arc between hook & uppercut â€” arm stays somewhat bent, palm tilts inward
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 1.08;
      sY = -sign * (0.48 + ext * 1.05);
      sX = (sign > 0 ? 0.25 : -0.30) - 0.25 + ext * 0.75;
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 0.30; // stays bent (shovel hook = angled hook)
      pY = -0.28 - ext * 0.25;                  // stays slightly supinated (drives inward)
      wX = -0.08 * ext;
      wZ = sign * ext * 0.12;
      break;
    }
    case 'corkscrew': {
      // Straight punch with extra forearm rotation twist = more pronation
      sZ = (sign > 0 ? 1.40 : 1.35) - ext * 1.18;
      sY = -sign * (0.28 + ext * 0.82);
      sX = (sign > 0 ? 0.25 : -0.30) + ext * 0.52;
      eZ = (sign > 0 ? 1.20 : 1.05) - ext * 1.12;
      pY = -0.28 + ext * 2.10;                  // PIVOT: extra rotation past full pronation = "corkscrew" âœ“
      wX = 0;
      wZ = -sign * ext * 0.18;                  // wrist deviation adds to twist
      break;
    }
    case 'haymaker': {
      // Big wind-back: shoulder externally rotates, then crashes with full body weight
      // windup (ext < 0.25): shoulder cocks back; active (ext > 0.25): crashes forward
      const windPct = Math.min(1, ext / 0.25);
      const crashPct = Math.max(0, (ext - 0.25) / 0.75);
      sZ = (sign > 0 ? 1.40 : 1.35) + windPct * 0.40 - crashPct * 1.35;
      sY = -sign * (-0.55 * windPct + (0.85 + crashPct * 1.55));
      sX = (sign > 0 ? 0.25 : -0.30) + windPct * 0.45 - crashPct * 0.10;
      eZ = (sign > 0 ? 1.20 : 1.05) + windPct * 0.10 - crashPct * 0.85;
      pY = -0.28 - windPct * 0.55 + crashPct * 1.70; // supinated wind â†’ full pronation crash
      wX = -0.10 * windPct;
      wZ = -sign * 0.12 * crashPct;
      break;
    }
  }

  arm.shoulderGrp.rotation.set(sX, sY, sZ);
  arm.elbowGrp.rotation.set(0, 0, eZ);      // HINGE: only Z
  arm.forearmPivot.rotation.set(0, pY, 0);  // PIVOT: only Y
  arm.wristGrp.rotation.set(wX, 0, wZ);     // CONDYLOID: X + Z
}

