// Guard defaults referenced by every case (so ext=0 returns to neutral)
const gSZ = (sign > 0 ? 1.40 : 1.35);
const gEZ = (sign > 0 ? 1.20 : 1.05);
const gSX = (sign > 0 ? 0.25 : -0.30);

switch (kind){
  case 'jab':
  case 'straight': {
    // Quick linear extension: shoulder turns forward, elbow extends, forearm pronates at impact
    sZ = gSZ - ext * 1.35;                       // shoulder elevation â†’ neutral as arm reaches
    sY = -sign * (0.18 + ext * 0.65);            // arm rotates horizontally toward opponent
    sX = gSX + ext * 0.55;                       // slight forward shoulder tilt at impact
    eZ = gEZ - ext * (gEZ - 0.07);               // HINGE: bent â†’ near-straight
    pY = -0.28 + ext * 1.55;                     // PIVOT: supinated guard â†’ full pronation âœ“
    wX = 0.09;
    wZ = -ext * 0.10;                            // slight radial deviation at impact
    break;
  }
  case 'cross': {
    // Rear-hand power shot: deeper shoulder turn, full pronation, full extension
    sZ = gSZ - ext * 1.38;
    sY = -sign * (0.20 + ext * 0.80);            // bigger horizontal rotation than jab
    sX = gSX + ext * 0.62;                       // shoulder drives forward harder
    eZ = gEZ - ext * (gEZ - 0.05);               // HINGE: extends fully on impact
    pY = -0.28 + ext * 1.70;                     // full pronation (palm down) âœ“
    wX = 0.09 - ext * 0.05;
    wZ = -ext * 0.08;
    break;
  }
  case 'hook': {
    // Classic horizontal hook: huge sY swing, elbow LOCKED bent (~85Â°+), partial pronation
    sZ = gSZ - ext * 0.75;
    sY = -sign * (0.55 + ext * 1.45);            // wide horizontal adduction sweep
    sX = gSX + ext * 0.32;
    eZ = Math.max(0.95, gEZ - ext * 0.18);       // HINGE: stays VERY bent (never < 0.95)
    pY = -0.28 + ext * 0.55;                     // palm tilts ~45Â° down at impact
    wX = -0.12 * ext;                            // wrist extends â€” knuckles lead
    wZ = sign * ext * 0.10;                      // slight ulnar deviation
    break;
  }
  case 'checkHook': {
    // Defensive pivot hook: tighter, more compact arc, quicker snap, elbow STAYS more bent
    sZ = gSZ - ext * 0.55;                       // less elevation change (compact)
    sY = -sign * (0.62 + ext * 1.10);            // smaller sweep than full hook
    sX = gSX + ext * 0.18;
    eZ = Math.max(1.05, gEZ - ext * 0.08);       // HINGE: barely opens (very tight, â‰¥1.05)
    pY = -0.28 + ext * 0.70;                     // a bit more pronated than hook (snappy)
    wX = -0.08 * ext;
    wZ = sign * ext * 0.14;                      // more ulnar deviation (tight snap)
    break;
  }
  case 'uppercut': {
    // Drives upward from low position: elbow flexes MORE, forearm SUPINATES (palm toward self)
    sZ = gSZ - ext * 1.55;                       // shoulder lifts arm strongly upward
    sX = gSX - 0.50 + ext * 1.05;                // shoulder dips on windup, drives forward+up on impact
    sY = -sign * (0.10 + ext * 0.40);            // small horizontal component
    eZ = Math.min(1.95, gEZ + ext * 0.55);       // HINGE: MORE bent at impact (drive up) âœ“ clamped
    pY = -0.28 - ext * 0.72;                     // PIVOT: MORE supinated (palm faces fighter) âœ“
    wX = -0.22 * ext;                            // wrist extends back slightly
    wZ = 0;
    break;
  }
  case 'overhand': {
    // Arcs OVER opponent's guard: shoulder winds back/over the top, then crashes down-forward
    // Windup (ext<0.25): shoulder X goes strongly negative (cocks over head)
    const wind = Math.min(1, ext / 0.25);
    const crash = Math.max(0, (ext - 0.25) / 0.75);
    sZ = gSZ - wind * 0.20 - crash * 0.95;        // arm lifts up & over, then comes down
