      sY = -sign * (0.55 + ext * 1.45);            // wide horizontal adduction sweep
      sX = gSX + ext * 0.32;
      eZ = Math.max(0.95, gEZ - ext * 0.18);       // HINGE: stays VERY bent (never < 0.95)
