      sX = gSX - wind * 0.85 + crash * 1.05;        // big negative tilt (back over head) â†’ forward crash âœ“
      eZ = Math.min(1.95, gEZ + wind * 0.25) - crash * 0.70;  // bent during arc, partly extends on crash
      pY = -0.28 - wind * 0.25 + crash * 1.45;      // supinated on windup â†’ pronated on impact
      wX = -0.05 * wind + 0.10 * crash;
