    hp: 100, maxHp: 100,
    stamina: 100, maxStam: 100,
    color: opts.color,
    trunks: opts.trunks,
    skin: opts.skin || 0xd6a26b,
    gloveColor: opts.gloveColor,
    action: 'idle',
    actionT: 0, actionDur: 0,
    activeArm: 'lead',
    actionKind: null,
    hitFrameDone: false,
    flinch: 0, flinchDir: 0, flinchHistory: 0,
    aiTimer: 0, aiState: 'idle',
    aiAggression: 0.5, aiReaction: 0.4,
