//  Input
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const keys = {};
const keyEdge = {}; // single-frame edge-triggered presses for punch keys
const PUNCH_KEYS = Object.keys(KEY_PUNCH);
const RESERVED = new Set(['w','a','s','d',' ', ...PUNCH_KEYS]);

window.addEventListener('keydown', e => {
  ensureAudio();
  const k = e.key.toLowerCase();
  if (RESERVED.has(k)) e.preventDefault();
  if (!keys[k]) keyEdge[k] = true;
  keys[k] = true;
});
window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

document.querySelectorAll('#touch-controls .touch-btn[data-tk]').forEach(btn => {
  const tk = btn.dataset.tk;
  btn.addEventListener('touchstart', e => { e.preventDefault(); ensureAudio(); if (!keys[tk]) keyEdge[tk] = true; keys[tk] = true; });
  btn.addEventListener('touchend',   e => { e.preventDefault(); keys[tk] = false; });
  btn.addEventListener('touchcancel',e => { keys[tk] = false; });
  // Mouse fallback for testing
  btn.addEventListener('mousedown', e => { e.preventDefault(); ensureAudio(); if (!keys[tk]) keyEdge[tk] = true; keys[tk] = true; });
  btn.addEventListener('mouseup',   e => { e.preventDefault(); keys[tk] = false; });
  btn.addEventListener('mouseleave',e => { keys[tk] = false; });
});

function consumeEdge(k){
  if (keyEdge[k]){ keyEdge[k] = false; return true; }
  return false;
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer logic
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function startAction(b, kind, sideOverride){
  if (b.hp <= 0) return;
  if (b.action === 'ko') return;
  if (b.stunned && kind !== 'block') return;
  if (b.action !== 'idle' && b.action !== 'block') return;
  if (kind in PUNCH){
    const p = PUNCH[kind];
    if (b.stamina < p.stam * 0.5) return;
    b.stamina = Math.max(0, b.stamina - p.stam);
    let arm;
    const handRule = PUNCH_HAND[kind];
    if (sideOverride) arm = sideOverride;
    else if (handRule === 'lead') arm = 'lead';
    else if (handRule === 'rear') arm = 'rear';
    else {
      arm = b.nextSide[kind] || 'lead';
      b.nextSide[kind] = (arm === 'lead') ? 'rear' : 'lead';
    }
    b.action = kind;
    b.actionKind = kind;
    b.actionT = 0;
    b.actionDur = p.windup + p.active + p.recover;
    b.activeArm = arm;
    b.hitFrameDone = false;
    b.punchesThrown++;
  } else if (kind === 'block'){
    b.action = 'block'; b.actionT = 0; b.actionDur = 0;
  }
}
function endAction(b){ b.action = 'idle'; b.actionT = 0; b.actionKind = null; }

function startDodge(b){
  if (b.hp <= 0 || b.action === 'ko') return;
  if (b.dodgeCooldown > 0) return;
  if (b.action !== 'idle') return;
  b.action = 'dodge';
  b.actionT = 0;
  b.actionDur = 0.38;
  b.dodgeCooldown = 0.9;
}

function zoneForHit(attacker, kind){
  const p = PUNCH[kind];
  if (p.zone !== 'RIBS') return p.zone;
  // Shovel hook: which side of opponent's torso depending on attacker's arm.
  // Attacker's left arm hits opponent's right ribs, and vice-versa.
  return (attacker.activeArm === 'lead') ? 'RIGHT_RIBS' : 'LEFT_RIBS';
  // (Lead = left arm in orthodox stance; "left arm hits right side" of opp.)
}

function zoneColorClass(amount){
  if (amount > 28) return 'red';
  if (amount > 12) return 'yellow';
  return 'white';
}
function zoneMultiplier(amount){
  if (amount > 28) return 1.25;
  if (amount > 12) return 1.10;
  return 1.0;
}

function takeHit(target, source, kind){
  const p = PUNCH[kind];
  const zone = zoneForHit(source, kind);
  const blocked = (target.action === 'block');

  // Dodge check â€” crouching slips jabs/hooks/most punches; uppercut punishes
  if (!blocked && target.kneesBent > 0.5 && target.action === 'dodge'){
    if (kind !== 'uppercut'){
      spawnHitText('DODGE!', target, '#44ff88');
      return;
    }
    spawnHitText('CAUGHT!', target, '#ff8800');
  }

  let dmg = p.dmg;
  // Check-hook bonus when hitting a target mid-windup
  if (kind === 'checkHook' && target.actionKind && target.action in PUNCH){
    const tp = PUNCH[target.action];
    if (target.actionT < tp.windup) dmg += 4;
  }
  // Liver = crit modifier
  if (kind === 'liverShot') dmg += 2;
  // Pre-existing zone damage multiplier (BEFORE we add this hit)

  dmg = dmg * zoneMultiplier(target.zoneDmg[zone] || 0);

  if (blocked){
    dmg = Math.round(dmg * 0.18);
    target.stamina = Math.max(0, target.stamina - p.stam * 0.6);
    playBlock();
    spawnHitText('BLOCK', target, '#9fdcff');
  } else {
    source.punchesLanded++;
    target.flinch = 0.35;
    target.flinchDir = (Math.random() < 0.5 ? -1 : 1);
    if (target.action !== 'ko') target.action = 'hit';
    target.actionT = 0;
    target.actionDur = p.windup + 0.05;
    // Knockback in 3D â€” push along the source-to-target vector (XZ plane only)
    const kbDir = new THREE.Vector3().subVectors(target.pos, source.pos);
    kbDir.y = 0;
    if (kbDir.lengthSq() < 0.0001) kbDir.set(target.facing, 0, 0);
    kbDir.normalize();
    target.pos.x += kbDir.x * p.knockback;
    target.pos.z += kbDir.z * p.knockback;
    playHit(p.power);
    spawnHitText(p.word, target, p.col);
    if (p.power >= 3) flashAmount = Math.max(flashAmount, 0.32);
    cameraShake = Math.max(cameraShake, p.power === 1 ? 0.05 : p.power === 2 ? 0.10 : 0.18);
    target.zoneDmg[zone] = (target.zoneDmg[zone] || 0) + dmg;
    // Stun roll â€” 10% per clean hit
    if (Math.random() < 0.10 && target.action !== 'ko'){
      target.stunned = true;
      target.stunT = 1.4;
      spawnHitText('STUNNED!', target, '#ff5e3a');
    }
  }
  target.hp -= dmg;
  if (target.hp <= 0){
    target.hp = 0;
    target.action = 'ko';
    target.actionT = 0;
    target.actionDur = 1.6;
    target.koStaggered = false;
    slowmoT = 1.5;
    flashAmount = 0.45;
    if (target.isPlayer) knockdownsPlayer++; else knockdownsCpu++;
  }
}

function checkPunchHit(attacker, defender){
  if (!(attacker.action in PUNCH)) return;
  const p = PUNCH[attacker.action];
  if (attacker.actionT < p.windup || attacker.actionT > p.windup + p.active) return;
  if (attacker.hitFrameDone) return;
  // 3D distance
  const dx = defender.pos.x - attacker.pos.x;
  const dz = defender.pos.z - attacker.pos.z;
  const dist = Math.sqrt(dx*dx + dz*dz);
  if (dist > p.range) return;
  if (dist < 0.05) return;
  // Forward cone: defender must be in front of attacker (yaw-based).
  const fwdX = Math.cos(attacker.yaw);
  const fwdZ = -Math.sin(attacker.yaw); // because root.rotation.y rotates around +Y
  const dot = (dx * fwdX + dz * fwdZ);
  if (dot < 0.6 * dist) return;
  attacker.hitFrameDone = true;
  takeHit(defender, attacker, attacker.action);
}

// Set yaw so defender's forward vector points toward target.
function aimYawAt(b, target){
  const dx = target.pos.x - b.pos.x;
  const dz = target.pos.z - b.pos.z;
  // forward = (cos(yaw), -sin(yaw)).  yaw = atan2(-dz, dx)
  b.targetYaw = Math.atan2(-dz, dx);
  // initialize current facing label for legacy bits
  b.facing = (Math.cos(b.targetYaw) >= 0) ? 1 : -1;
}

function clampToRing(b){
  const r = RING_HALF - 0.4;
  if (b.pos.x >  r) b.pos.x =  r;
  if (b.pos.x < -r) b.pos.x = -r;
  if (b.pos.z >  r) b.pos.z =  r;
  if (b.pos.z < -r) b.pos.z = -r;
}

function tickPlayer(b, dt){
  aimYawAt(b, cpu);
  // Forward / right vectors based on yaw
  const fwdX = Math.cos(b.yaw),  fwdZ = -Math.sin(b.yaw);
  const rgtX = Math.sin(b.yaw),  rgtZ =  Math.cos(b.yaw);

  let fIn = 0, sIn = 0;
  if (keys['w']) fIn += 1;
  if (keys['s']) fIn -= 1;
  if (keys['a']) sIn -= 1;
  if (keys['d']) sIn += 1;

  let speed = (b.action === 'idle' || b.action === 'block') ? 2.4 : 0.6;
  if (b.stunned) speed *= 0.4;

  if (b.action !== 'ko' && b.action !== 'hit'){
    // W = approach (toward enemy = forward). S = retreat (back).
    // A/D = strafe â€” that's how we circle.
    b.pos.x += (fIn * fwdX + sIn * rgtX) * speed * dt;
    b.pos.z += (fIn * fwdZ + sIn * rgtZ) * speed * dt;
  }
  clampToRing(b);

  // Leg phase advances when moving
  if (b.action !== 'ko' && (fIn !== 0 || sIn !== 0)){
    b.legPhase = (b.legPhase + dt * 3.8) % 1;
  }

  if (b.action === 'block' && !keys[' ']) endAction(b);

  if ((b.action === 'idle' || b.action === 'block') && !b.stunned){
    if (keys[' ']){
      if (b.action !== 'block') startAction(b, 'block');
    } else {
      // Dodge (edge-triggered so a held key fires once)
      if (b.action === 'idle' && consumeEdge('q')) {
        startDodge(b);
      } else {
        // Edge-triggered punches so a held key only fires once.
        for (const k of PUNCH_KEYS){
          if (consumeEdge(k)){
            startAction(b, KEY_PUNCH[k]);
            break;
          }
        }
      }
    }
  } else {
    // Drain edge events that came in while we were locked out.
    for (const k of PUNCH_KEYS) keyEdge[k] = false;
  }
  tickAction(b, dt);
}

function tickAction(b, dt){
  // Always-running timers
  if (b.dodgeCooldown > 0) b.dodgeCooldown = Math.max(0, b.dodgeCooldown - dt);
  if (b.action !== 'dodge') b.kneesBent = Math.max(0, b.kneesBent - dt * 6);
  if (b.flinch > 0) b.flinch = Math.max(0, b.flinch - dt);

  // Stun timer
  if (b.stunned){
    b.stunT -= dt;
    b.stamina = Math.max(0, b.stamina - 4 * dt);
    if (b.stunT <= 0){ b.stunned = false; b.stunT = 0; }
  }

  if (b.action === 'ko'){ b.actionT += dt; return; }
  if (b.action === 'hit'){
    b.actionT += dt;
    if (b.actionT >= b.actionDur) endAction(b);
    return;
  }
  if (b.action === 'block'){
    b.stamina = Math.max(0, b.stamina - 4 * dt);
    return;
  }
  if (b.action === 'dodge'){
    b.actionT += dt;
    b.kneesBent = Math.sin((b.actionT / b.actionDur) * Math.PI);
    if (b.actionT >= b.actionDur){ b.kneesBent = 0; endAction(b); }
    return;
  }
  if (b.action in PUNCH){
    b.actionT += dt;
    if (b.actionT >= b.actionDur) endAction(b);
  }
  if (b.action === 'idle' && b.stamina < b.maxStam){
    const regen = b.stunned ? 6 : 18;
    b.stamina = Math.min(b.maxStam, b.stamina + regen * dt);
  }
  // Track low-stamina ticks for corner advice
  if (b.stamina < 30) b.lowStaminaTicks += dt;
}

// CPU AI â€” circling, 2D motion, varied punches.
function tickCpu(c, dt){
  aimYawAt(c, player);
  c.aiTimer    -= dt;
  c.circleTimer -= dt;
  if (c.circleTimer <= 0){
    c.circleTimer = 1.5 + Math.random() * 1.5;
    c.circleDir   = (Math.random() < 0.5 ? -1 : 1);
  }

  const dx = player.pos.x - c.pos.x;
  const dz = player.pos.z - c.pos.z;
  const dist = Math.sqrt(dx*dx + dz*dz);

  const playerThreatening =
    (player.action === 'hook' || player.action === 'uppercut' || player.action === 'haymaker' || player.action === 'overhand')
    && player.actionT < (PUNCH[player.action]?.windup || 0);
  if (playerThreatening && dist < 1.7 && Math.random() < c.aiReaction * dt * 60){
    if (c.dodgeCooldown <= 0 && Math.random() < 0.38) startDodge(c);
    else if (c.action === 'idle') startAction(c, 'block');
  } else if (c.action === 'block' && (!playerThreatening || dist > 2.0)){
    endAction(c);
  }

  if (c.action === 'idle' && !c.stunned){
    if (c.aiTimer <= 0){
      c.aiTimer = 0.3 + Math.random() * 0.6;
      if (dist > 3.0)         c.aiState = 'advance';
      else if (dist > 1.6){
        if (Math.random() < c.aiAggression) c.aiState = (Math.random() < 0.5 ? 'advance' : 'jab');
        else c.aiState = 'circle';
      } else {
        if (c.stamina < 25) c.aiState = 'retreat';
        else {
          const r = Math.random();
          if (r < c.aiAggression * 0.55){
            // Pick a random punch â€” wider variety than 3 originally.
            const choices = ['jab','cross','hook','uppercut','overhand','bodyShot','liverShot','straight','shovelHook','corkscrew'];
            c.aiState = choices[Math.floor(Math.random() * choices.length)];
            if (Math.random() < 0.07) c.aiState = 'haymaker';
          } else if (r < 0.85) c.aiState = 'circle';
          else c.aiState = 'block-tactical';
        }
      }
    }
    // Compute movement
    let fIn = 0, sIn = 0;
    if (c.aiState === 'advance')      fIn = 1;
    else if (c.aiState === 'retreat') fIn = -1;
    else if (c.aiState === 'circle')  fIn = 0;
    else if (c.aiState in PUNCH){ startAction(c, c.aiState); }
    else if (c.aiState === 'block-tactical'){ startAction(c, 'block'); }
    // Always add a circling component
    sIn += c.circleDir * 0.7;

    const fwdX = Math.cos(c.yaw),  fwdZ = -Math.sin(c.yaw);
    const rgtX = Math.sin(c.yaw),  rgtZ =  Math.cos(c.yaw);
    let speed = 1.7;
    if (c.stunned) speed *= 0.4;
    c.pos.x += (fIn * fwdX + sIn * rgtX) * speed * dt;
    c.pos.z += (fIn * fwdZ + sIn * rgtZ) * speed * dt;
    clampToRing(c);
    // CPU leg phase
    if ((fIn !== 0 || sIn !== 0) && c.action !== 'ko'){
      c.legPhase = (c.legPhase + dt * 3.8) % 1;
    }
  }
  tickAction(c, dt);
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer animation
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const _v3 = new THREE.Vector3();

function animateBoxer(b, dt){
  const r = b.rig;
  r.root.position.x = b.pos.x;
  r.root.position.z = b.pos.z;

  // Smooth yaw turn
  let dy = b.targetYaw - b.yaw;
  while (dy > Math.PI) dy -= Math.PI * 2;
  while (dy < -Math.PI) dy += Math.PI * 2;
  b.yaw += dy * Math.min(1, dt * 10);
  r.root.rotation.y = b.yaw;

  // KO fall
  if (b.action === 'ko'){
    if (!b.koStaggered){
      const staggerT = Math.min(1, b.actionT / 0.25);
      r.root.position.x += Math.sin(b.actionT * 60) * 0.08 * (1 - staggerT);
      if (b.actionT > 0.25) b.koStaggered = true;
    }
    const t = Math.min(1, Math.max(0, (b.actionT - 0.25)) / 0.6);
    r.root.rotation.x = t * (Math.PI/2);
    r.root.position.y = -t * 0.15;
  } else {
    r.root.rotation.x = 0;
    r.root.position.y = -b.kneesBent * 0.18;
  }

  const tNow = performance.now() * 0.001;

  // Breathing & idle bob
  let breath = 0, lateralShift = 0;
  if (b.action === 'idle' && b.hp > 0){
    breath = Math.sin(tNow * 2.2) * 0.025;
    lateralShift = Math.sin(tNow * 1.4) * 0.012;
    // Boxer bob: lead shoulder slightly up-down, thoracic breathes with slight twist
    r.thoracic.rotation.y = 0.06 + Math.sin(tNow * 2.2) * 0.04;
    r.armL.shoulderGrp.rotation.z = 1.35 - Math.sin(tNow * 2.2) * 0.05;
    r.armR.shoulderGrp.rotation.z = 1.40 + Math.sin(tNow * 2.2) * 0.03;
  }
  r.chest.scale.y = 1.0 + breath * 0.4;
  r.lumbar.position.x = lateralShift;

  // Stun sway â€” thoracic rocks, stars orbit
  if (b.stunned){
    r.lumbar.position.x += Math.sin(tNow * 6) * 0.06;
    r.thoracic.rotation.z = Math.sin(tNow * 6) * 0.10;
    r.stunGroup.visible = true;
    for (let i = 0; i < r.stars.length; i++){
      const a = tNow * 1.2 + i * (Math.PI*2/3);
      r.stars[i].position.set(Math.cos(a) * 0.22, Math.sin(tNow * 4 + i) * 0.04, Math.sin(a) * 0.22);
    }
  } else {
    r.stunGroup.visible = false;
    if (b.action !== 'hit') r.thoracic.rotation.z = (r.thoracic.rotation.z || 0) * (1 - dt * 8);
  }

  // Forward lean â€” drives lumbar rotation around X (L5-S1 pivot)
  let targetLeanX = 0.06; // base forward lean = boxing crouch
  if (b.action === 'idle'){
    if (b.isPlayer){
      if (keys['w']) targetLeanX = 0.14;
      else if (keys['s']) targetLeanX = -0.06;
    } else {
      if (b.aiState === 'advance') targetLeanX = 0.12;
      else if (b.aiState === 'retreat') targetLeanX = -0.06;
    }
  }
  if (b.action in PUNCH) targetLeanX = 0.20;
  r.lumbar.rotation.x = (r.lumbar.rotation.x || 0.06) + (targetLeanX - (r.lumbar.rotation.x || 0.06)) * Math.min(1, dt * 6);

  // Spine twist during punches (thoracic Y rotation)
  let targetSpineTwist = 0.06; // base orthodox lean
  let hipTwist = 0;
  if (b.action in PUNCH){
    const tp = b.actionT / Math.max(0.001, b.actionDur);
    const spinePulse = Math.sin(tp * Math.PI);
    const isRear = (b.activeArm === 'rear');
    // Cross/straight/haymaker use heavy spine rotation; hook medium; jab light
    const spineScale =
      (b.action === 'cross' || b.action === 'corkscrew' || b.action === 'haymaker') ? 0.45 :
      (b.action === 'hook' || b.action === 'overhand' || b.action === 'shovelHook') ? 0.28 :
      (b.action === 'uppercut') ? 0.15 : 0.10;
    targetSpineTwist = 0.06 + spinePulse * spineScale * (isRear ? -1 : 1);
    hipTwist = spinePulse * 0.18 * (isRear ? -1 : 1);
  }
  if (b.action !== 'idle') r.thoracic.rotation.y = (r.thoracic.rotation.y || 0.06) + (targetSpineTwist - (r.thoracic.rotation.y || 0.06)) * Math.min(1, dt * 10);

  // Hip counter-rotation drives the leg groups
  r.legL.hipGrp.rotation.y = hipTwist * 0.6;
  r.legR.hipGrp.rotation.y = hipTwist * 0.6;

  // â”€â”€ Stepping animation (hip Z swing + knee flex + ankle) â”€â”€
  const isMoving = b.action !== 'ko' && (
    b.isPlayer
      ? (keys['w'] || keys['a'] || keys['s'] || keys['d'])
      : (b.aiState === 'advance' || b.aiState === 'retreat' || b.aiState === 'circle')
  );
  if (isMoving){
    const phL = Math.sin(b.legPhase * Math.PI * 2);
    const phR = Math.sin(b.legPhase * Math.PI * 2 + Math.PI);
    r.legL.hipGrp.rotation.z = phL * 0.28;
    r.legR.hipGrp.rotation.z = phR * 0.28;
    // Knee: bends when leg lifts (swing phase)
    r.legL.kneeGrp.rotation.z = (phL > 0 ? -0.32 : -0.08);
    r.legR.kneeGrp.rotation.z = (phR > 0 ? -0.32 : -0.08);
    // Ankle: dorsiflexes on lift, plantarflexes on push-off
    r.legL.ankleGrp.rotation.z = 0.14 + (phL > 0 ? 0.16 : -0.18);
    r.legR.ankleGrp.rotation.z = 0.14 + (phR > 0 ? 0.16 : -0.18);
  } else {
    r.legL.hipGrp.rotation.z = (r.legL.hipGrp.rotation.z || 0) * (1 - Math.min(1, dt * 12));
    r.legR.hipGrp.rotation.z = (r.legR.hipGrp.rotation.z || 0) * (1 - Math.min(1, dt * 12));
    // Soft knees at rest
    const kRest = -0.14 - b.kneesBent * 0.88;
    r.legL.kneeGrp.rotation.z = kRest;
    r.legR.kneeGrp.rotation.z = kRest;
    // Ankle: dorsiflexion increases in dodge crouch
    const aBase = 0.14 + b.kneesBent * 0.18;
    r.legL.ankleGrp.rotation.z = aBase;
    r.legR.ankleGrp.rotation.z = aBase;
  }
  // Hip forward flex during dodge crouch (ball-and-socket)
  const hipFwd = b.kneesBent * 0.20;
  r.legL.hipGrp.rotation.x = hipFwd;
  r.legR.hipGrp.rotation.x = hipFwd;

  // â”€â”€ Muscle bulge â€” scale driven by joint angle â”€â”€
  if (b.action !== 'ko'){
    for (const arm of [r.armL, r.armR]){
      const eFlex = Math.abs(arm.elbowGrp.rotation.z);
      // Bicep swells as elbow bends (hinge = anatomically correct)
      arm.bicepMesh.scale.y = 1.5 + eFlex * 0.40;
      arm.bicepMesh.scale.x = 1.1 + eFlex * 0.20;
      // Deltoid flares with shoulder abduction (deviation from neutral guard)
      const abduct = Math.max(0, Math.abs(arm.shoulderGrp.rotation.z) - 0.6);
      arm.deltoidMesh.scale.z = 1.4 + abduct * 0.30;
    }
    // Quad swells with knee flex
    const kBendL = Math.abs(r.legL.kneeGrp.rotation.z);
    const kBendR = Math.abs(r.legR.kneeGrp.rotation.z);
    r.legL.quadMesh.scale.x = 0.65 + kBendL * 0.18;
    r.legR.quadMesh.scale.x = 0.65 + kBendR * 0.18;
    // Calf swells on plantarflexion (ankle bends backward)
    const pFlex = Math.max(0, 0.14 - r.legL.ankleGrp.rotation.z);
    const pFlexR = Math.max(0, 0.14 - r.legR.ankleGrp.rotation.z);
    r.legL.calfMesh.scale.x = 0.75 + pFlex * 0.50;
    r.legR.calfMesh.scale.x = 0.75 + pFlexR * 0.50;

  }

  // â”€â”€ Head tracking via atlanto-axial pivot (Y) â”€â”€
  const opp = b.isPlayer ? cpu : player;
  if (opp){
    _v3.subVectors(opp.pos, b.pos);
    const localAngle = Math.atan2(-_v3.z, _v3.x) - b.yaw;
    let la = localAngle;
    while (la > Math.PI) la -= Math.PI*2;
    while (la < -Math.PI) la += Math.PI*2;
    r.neckPivot.rotation.y = la * 0.35;
  }

  // â”€â”€ Flinch â€” split by joint: neckNod (Z = back snap) + neckNod.x (lateral) â”€â”€
  if (b.flinch > 0 && b.action !== 'ko'){
    const ft = b.flinch;
    const jerk = Math.min(1, (0.35 - ft) / 0.15);
    const recoil = Math.max(0, 1 - jerk);
    // Z = head snaps back (atlanto-occipital nod axis)
    r.neckNod.rotation.z = -(jerk * 0.38 + recoil * 0.14);
    // X = lateral tilt from flinchDir
    r.neckNod.rotation.x = (-b.flinchDir) * (jerk * 0.22 + recoil * 0.08);
  } else {
    r.neckNod.rotation.z = (r.neckNod.rotation.z || 0) * (1 - dt * 10);
    r.neckNod.rotation.x = (r.neckNod.rotation.x || 0) * (1 - dt * 10);
  }

  // Default guard pose (resets non-punching arm each frame)
  r.setGuardPose();

  // Per-punch arm + spine animation
  if (b.action in PUNCH){
    const kind = b.action;
    const p = PUNCH[kind];
    const phase =
      (b.actionT < p.windup) ? (b.actionT / p.windup) :
      (b.actionT < p.windup + p.active) ? (1 + (b.actionT - p.windup) / Math.max(0.001, p.active)) :
      (2 + (b.actionT - p.windup - p.active) / Math.max(0.001, p.recover));
    animatePunch(b, kind, phase);
  } else if (b.action === 'block'){
    setArmPose(r.armL, { sRot:[-0.20, 0, 1.55], eRot:[0,0,1.25], pRot:[0,0.10,0], wRot:[0.05,0,0] });
    setArmPose(r.armR, { sRot:[ 0.20, 0, 1.55], eRot:[0,0,1.25], pRot:[0,0.10,0], wRot:[0.05,0,0] });
  } else if (b.action === 'hit'){
    setArmPose(r.armL, { sRot:[-0.20, 0, 1.20], eRot:[0,0,1.05], pRot:[0,-0.20,0], wRot:[0.05,0,0] });
    setArmPose(r.armR, { sRot:[ 0.20, 0, 1.20], eRot:[0,0,1.05], pRot:[0,-0.20,0], wRot:[0.05,0,0] });
  }
}

// Drive an arm by punch family + phase (0..3).
// Each joint is constrained to its anatomical axes:
//   shoulderGrp: 3-axis (ball-and-socket)
//   elbowGrp:    Z only (hinge)
//   forearmPivot:Y only (pivot = pronation/supination)
//   wristGrp:    X + Z only (condyloid)
function animatePunch(b, kind, phase){
  const r = b.rig;
  const arm = (b.activeArm === 'lead') ? r.armL : r.armR;
  const sign = (b.activeArm === 'lead') ? -1 : 1;

  const ext = (phase < 1) ? (phase * 0.25) :
              (phase < 2) ? (0.25 + 0.75 * (phase - 1)) :
              Math.max(0, 1 - (phase - 2));

  // Separate elbow timing so the joint visibly cocks then snaps straight.
  // eBend:   0â†’1 during windup  (elbow flexes MORE = arm cocks)
  //          1â†’0 during active  (elbow extends = arm launches)
  //          0   during recover
  // eStrike: 0   during windup
  //          0â†’1 during active  (drives extension)
  //          1â†’0 during recover
  const eBend   = (phase < 1) ? phase : (phase < 2) ? (2 - phase) : 0;
  const eStrike = (phase < 1) ? 0 : (phase < 2) ? (phase - 1) : Math.max(0, 1 - (phase - 2));

  const gSZ = (sign > 0 ? 1.40 : 1.35);
  const gEZ = (sign > 0 ? 1.20 : 1.05);
  const gSX = (sign > 0 ? 0.25 : -0.30);

  let sX = gSX, sY = 0, sZ = gSZ;
  let eZ = gEZ;
  let pY = -0.28;
  let wX = 0.09, wZ = 0;

  switch (kind){

    case 'jab':
    case 'straight': {
      // Shoulder sweeps forward (Y), arm stays elevated (Z drops less).
      // Elbow cocks back during windup then SNAPS straight â€” the key visible motion.
      sZ = gSZ - ext * 0.55;                     // arm stays fairly elevated throughout
      sY = -sign * ext * 0.85;                   // drives arm toward opponent
      sX = gSX + ext * 0.35;
      eZ = gEZ + eBend * 0.50                    // WINDUP: cocks to ~1.55 (clearly more bent)
             - eStrike * (gEZ + 0.50 - 0.08);   // STRIKE:  snaps to 0.08 (nearly straight) âœ“
      pY = -0.28 + ext * 1.55;                   // supinated guard â†’ full pronation at impact
      wX = 0.09;
      wZ = -ext * 0.08;
      break;
    }

    case 'cross': {
      // Same snap as jab but rear hand â€” more shoulder drive, deeper reach.
      sZ = gSZ - ext * 0.60;
      sY = -sign * ext * 1.00;
      sX = gSX + ext * 0.55;
      eZ = gEZ + eBend * 0.55
             - eStrike * (gEZ + 0.55 - 0.06);   // snaps to 0.06 âœ“
      pY = -0.28 + ext * 1.70;
      wX = 0.09 - ext * 0.05;
      wZ = -ext * 0.08;
      break;
    }

    case 'hook': {
      // Elbow stays LOCKED â€” the bent arm SWINGS as one unit around the shoulder Y axis.
      // Elbow only tightens slightly on windup, DOES NOT straighten at impact.
      sZ = gSZ - ext * 0.70;
      sY = -sign * (0.50 + ext * 1.50);          // big horizontal sweep
      sX = gSX + ext * 0.28;
      eZ = gEZ + eBend * 0.20                    // slight extra cock on windup
             - eStrike * 0.10;                   // barely opens at impact (stays ~gEZ) âœ“
      eZ = Math.max(0.90, eZ);                   // never below 90Â° â€” hook rule
      pY = -0.28 + ext * 0.50;                   // partial pronation (palm ~45Â°)
      wX = -0.12 * ext;
      wZ = sign * ext * 0.10;
      break;
    }

    case 'checkHook': {
      // Compact defensive hook â€” very tight elbow, quick snap.
      sZ = gSZ - ext * 0.45;
      sY = -sign * (0.60 + ext * 1.05);
      sX = gSX + ext * 0.15;
      eZ = gEZ + eBend * 0.15 - eStrike * 0.08;
      eZ = Math.max(1.05, eZ);
      pY = -0.28 + ext * 0.65;
      wX = -0.08 * ext;
      wZ = sign * ext * 0.12;
      break;
    }

    case 'uppercut': {
      // Elbow BENDS MORE at impact (not less). Forearm stays SUPINATED (palm toward self).
      // Shoulder dips on windup, drives UP on strike.
      sZ = gSZ - eStrike * 1.50;                // arm rises sharply only during strike
      sX = gSX - eBend * 0.45 + eStrike * 0.90; // dips back, then drives forward-up
      sY = -sign * (0.10 + ext * 0.38);
      eZ = gEZ + eBend * 0.30                   // slight cock
             + eStrike * 0.60;                  // MORE BENT at impact: gEZ+0.90 â‰ˆ 1.95 âœ“
      eZ = Math.min(1.95, eZ);
      pY = -0.28 - eBend * 0.35 - eStrike * 0.55; // stays supinated throughout âœ“
      wX = -0.20 * eStrike;
      wZ = 0;
      break;
    }

    case 'overhand': {
      // Arm arcs OVER the top: shoulder cocks high on windup, crashes down-forward on strike.
      sZ = gSZ + eBend * 0.40 - eStrike * 1.10; // rises during windup, drops hard on strike
      sY = -sign * (0.22 + eBend * 0.28 + eStrike * 0.85);
      sX = gSX - eBend * 0.80 + eStrike * 1.00; // leans back on windup, crashes forward âœ“
      eZ = gEZ + eBend * 0.35                   // cocks on windup
             - eStrike * (gEZ + 0.35 - 0.35);   // extends partially on crash
      pY = -0.28 - eBend * 0.20 + eStrike * 1.45;
      wX = -0.05 * eBend + 0.08 * eStrike;
      wZ = -ext * 0.06;
      break;
    }

    case 'bodyShot': {
      // Shoulder drops DOWN, elbow cocks then extends into the ribs.
      sZ = gSZ - ext * 0.80;
      sY = -sign * (0.28 + ext * 0.65);
      sX = gSX - ext * 0.55;                    // shoulder tilts downward âœ“
      eZ = gEZ + eBend * 0.40
             - eStrike * (gEZ + 0.40 - 0.35);  // extends to moderate bend (arm downward)
      pY = -0.28 + ext * 1.05;
      wX = 0.18 * eStrike;                      // wrist flexes into ribs
      wZ = 0;
      break;
    }

    case 'liverShot': {
      // Drops even further, drives inward under right rib cage.
      sZ = gSZ - ext * 0.90;
      sY = -sign * (0.20 + ext * 0.60);
      sX = gSX - ext * 0.65;                    // biggest downward tilt âœ“
      eZ = gEZ + eBend * 0.30
             - eStrike * (gEZ + 0.30 - 0.55);  // extends to ~0.55 (hook-into-liver bend)
      pY = -0.28 + ext * 1.20;
      wX = 0.14 * eStrike;
      wZ = sign * ext * 0.18;                   // ulnar deviation drives into liver âœ“
      break;
    }

    case 'shovelHook': {
      // Diagonal between hook (horizontal) and uppercut (upward).
      // Elbow stays bent like a hook but shoulder drives diagonally upward.
      sZ = gSZ - ext * 1.10;                    // shoulder elevation drops (midway)
      sY = -sign * (0.38 + ext * 0.92);
      sX = gSX - eBend * 0.25 + eStrike * 0.60; // dips then drives diagonally up
      eZ = gEZ + eBend * 0.25
             - eStrike * 0.20;                  // barely extends â€” hook trait âœ“
      eZ = Math.max(0.85, eZ);
      pY = -0.28 - ext * 0.12;                  // slight supination
      wX = -0.10 * eStrike;
      wZ = sign * ext * 0.10;
      break;
    }

    case 'corkscrew': {
      // Straight extension with extra forearm twist well past full pronation.
      sZ = gSZ - ext * 0.55;
      sY = -sign * ext * 0.88;
      sX = gSX + ext * 0.40;
      eZ = gEZ + eBend * 0.50
             - eStrike * (gEZ + 0.50 - 0.07);  // snaps fully straight âœ“
      pY = -0.28 + ext * 2.10;                  // WAY past pronation = the corkscrew twist âœ“
      wX = 0.05 - ext * 0.10;
      wZ = -sign * ext * 0.22;
      break;
    }

    case 'haymaker': {
      // Huge wind-back: shoulder cocks all the way back, then swings with full body.
      // Windup is longer and more dramatic than any other punch.
      sZ = gSZ + eBend * 0.55 - eStrike * 1.35;  // arm lifts back on windup, crashes on strike
      sY = -sign * (-0.70 * eBend + (0.90 + eStrike * 1.55)); // rotates BACK then FORWARD âœ“
      sX = gSX + eBend * 0.55 - eStrike * 0.18;
      eZ = gEZ + eBend * 0.60                    // cocks DEEPLY (gEZ+0.60 â‰ˆ 1.80)
             - eStrike * (gEZ + 0.60 - 0.10);   // crashes to 0.10 (nearly straight)
      pY = -0.28 - eBend * 0.65 + eStrike * 1.85; // supinated windup â†’ full pronation crash âœ“
      wX = -0.15 * eBend + 0.05 * eStrike;
      wZ = -sign * 0.14 * eStrike;
      break;
    }
  }

  if (eZ > 2.0) eZ = 2.0;
  if (eZ < 0)   eZ = 0;

  arm.shoulderGrp.rotation.set(sX, sY, sZ);
  arm.elbowGrp.rotation.set(0, 0, eZ);      // HINGE: only Z
  arm.forearmPivot.rotation.set(0, pY, 0);  // PIVOT: only Y
  arm.wristGrp.rotation.set(wX, 0, wZ);     // CONDYLOID: X + Z
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Hit-text bursts
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const hitBursts = [];
function spawnHitText(word, target, color){
  const el = document.createElement('div');
  el.className = 'hit-burst';
  el.textContent = word;
  el.style.color = color;
  document.body.appendChild(el);
  hitBursts.push({ el, t: 0, life: 0.7, color, follow: target });
}
function updateHitBursts(dt){
  for (let i = hitBursts.length - 1; i >= 0; i--){
    const h = hitBursts[i];
    h.t += dt;
    const a = 1 - (h.t / h.life);
    if (a <= 0){ h.el.remove(); hitBursts.splice(i, 1); continue; }
    const target = h.follow;
    const v = new THREE.Vector3(target.pos.x, 2.4, target.pos.z);
    v.project(camera);
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight - (1 - a) * 60;
    h.el.style.transform = 'translate(-50%,-50%) scale(' + (1 + (1 - a) * 0.4) + ')';
    h.el.style.left = x + 'px';
    h.el.style.top  = y + 'px';
    h.el.style.opacity = a;
  }
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  HUD
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function updateHud(){
  if (!player || !cpu) return;
  document.getElementById('hp-p').style.width = (player.hp / player.maxHp * 100) + '%';
  document.getElementById('hp-c').style.width = (cpu.hp / cpu.maxHp * 100) + '%';
  document.getElementById('stam-p').style.width = (player.stamina / player.maxStam * 100) + '%';
  document.getElementById('stam-c').style.width = (cpu.stamina / cpu.maxStam * 100) + '%';
  document.getElementById('hp-p-num').textContent = Math.round(player.hp);
  document.getElementById('hp-c-num').textContent = Math.round(cpu.hp);
  const m = Math.floor(roundClock / 60);
  const s = Math.floor(roundClock % 60);
  document.getElementById('round-time').textContent = m + ':' + (s < 10 ? '0' : '') + s;
  document.getElementById('round-time').classList.toggle('danger', roundClock < 10);
  document.getElementById('round-score').textContent = scorePlayer + '-' + scoreCpu;
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Main loop
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
let lastT = performance.now();
function loop(now){
  requestAnimationFrame(loop);
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (dt > 0.1) dt = 0.1;
  if (slowmoT > 0){ slowmoT -= dt; dt *= 0.32; }

  if (state === 'fight') update(dt);

  if (player) animateBoxer(player, dt);
  if (cpu)    animateBoxer(cpu,    dt);

  updateHitBursts(dt);
  updateHud();
  updateCamera(dt);

  // Glove raise celebration
  if (gloveRaiseMode){
    gloveRaiseMode.t += dt;
    const winner = gloveRaiseMode.who === 'player' ? player : cpu;
    if (winner && winner.rig){
      const t = Math.min(1, gloveRaiseMode.t / 0.8);
      const eased = 1 - Math.pow(1 - t, 3);
      const rear = winner.rig.armR;
      rear.shoulderGrp.rotation.set(-0.10, -0.60, -2.60 + eased * 0.60);
      rear.elbowGrp.rotation.set(0, 0, 0.75);  // arm bent triumphantly
      rear.forearmPivot.rotation.set(0, -0.40, 0); // slight supination = fist faces crowd
      rear.wristGrp.rotation.set(-0.10, 0, 0);
    }
  }

  // Crowd backlight pulse
  back.intensity = backBaseIntensity + Math.max(0, backPulse);
  backPulse = Math.max(0, backPulse - dt * 0.8);

  // Flash
  if (flashAmount > 0){
    document.getElementById('flash').style.opacity = flashAmount;
    flashAmount = Math.max(0, flashAmount - dt * 1.6);
  } else {
    document.getElementById('flash').style.opacity = 0;
  }

  renderer.render(scene, camera);
}

// Third-person follow camera.
function updateCamera(dt){
  if (!player) return;
  // Anchor the "view subject".  Normally the player; during glove raise, the winner.
  const subject = (gloveRaiseMode && gloveRaiseMode.who === 'cpu') ? cpu : player;
  const otherFighter = (subject === player) ? cpu : player;

  // Forward (subject) â†’ opponent direction in XZ.
  const dirX = (otherFighter.pos.x - subject.pos.x);
  const dirZ = (otherFighter.pos.z - subject.pos.z);
  const len = Math.max(0.001, Math.sqrt(dirX*dirX + dirZ*dirZ));
  const fX = dirX / len, fZ = dirZ / len;

  let backDist = 3.0;
  let upHeight = 2.2;
  let lookAhead = 0.8;
  if (gloveRaiseMode){
    backDist = 1.8;
    upHeight = 1.9;
    lookAhead = 0.0;
  }

  // Camera sits behind the subject (opposite of forward), slightly elevated.
  camDesiredPos.set(
    subject.pos.x - fX * backDist,
    subject.pos.y + upHeight,
    subject.pos.z - fZ * backDist
  );
  // Look toward the opponent / subject head height.
  camDesiredTarget.set(
    subject.pos.x + fX * lookAhead,
    subject.pos.y + 1.5,
    subject.pos.z + fZ * lookAhead
  );

  const k = Math.min(1, dt * 6);
  camPos.lerp(camDesiredPos, k);
  camTarget.lerp(camDesiredTarget, k);

  const shakeX = cameraShake > 0 ? (Math.random() - 0.5) * cameraShake : 0;
  const shakeY = cameraShake > 0 ? (Math.random() - 0.5) * cameraShake : 0;
  if (cameraShake > 0) cameraShake = Math.max(0, cameraShake - dt * 1.6);

  camera.position.set(camPos.x + shakeX, camPos.y + shakeY, camPos.z);
  camera.lookAt(camTarget);
}

function update(dt){
  roundClock -= dt;
  tickPlayer(player, dt);
  tickCpu(cpu, dt);
  checkPunchHit(player, cpu);
  checkPunchHit(cpu, player);
  if (player.hp <= 0 || cpu.hp <= 0){
    state = 'roundover';
    showBanner(player.hp <= 0 ? 'YOU GOT KO\'D' : 'KNOCKOUT!');

    setTimeout(roundEnd, 1700);
  } else if (roundClock <= 0){
    roundClock = 0;
    state = 'roundover';
    showBanner('END OF ROUND ' + round);
    setTimeout(roundEnd, 1100);
  }
}

function showBanner(text){
  const b = document.getElementById('round-banner');
  b.textContent = text;
  b.classList.add('show');
  setTimeout(() => b.classList.remove('show'), 1600);
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Damage diagram + corner advice (between rounds)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function totalZoneDamage(zoneDmg){
  let s = 0;
  for (const k in zoneDmg) s += zoneDmg[k] || 0;
  return s;
}

function buildBodySvg(zoneDmg){
  // Six zones as colored regions.
  const col = {
    HEAD:       zoneFill(zoneDmg.HEAD),
    CHEST:      zoneFill(zoneDmg.CHEST),
    ABS:        zoneFill(zoneDmg.ABS),
    LIVER:      zoneFill(zoneDmg.LIVER),
    LEFT_RIBS:  zoneFill(zoneDmg.LEFT_RIBS),
    RIGHT_RIBS: zoneFill(zoneDmg.RIGHT_RIBS),
  };
  // Numbers shown as small labels.
  const n = (z)=> Math.round(zoneDmg[z] || 0);
  return `
  <svg viewBox="0 0 160 230" width="160" height="230">
    <!-- Head -->
    <ellipse cx="80" cy="32" rx="22" ry="26" fill="${col.HEAD}" stroke="#ffd700" stroke-width="1.5"/>
    <text x="80" y="35" text-anchor="middle" font-size="9" fill="#000" font-weight="bold">HEAD ${n('HEAD')}</text>
    <!-- Neck -->
    <rect x="71" y="56" width="18" height="10" fill="#c89a55" stroke="#5a3f24" stroke-width="1"/>
    <!-- Shoulders -->
    <rect x="38" y="66" width="84" height="14" rx="6" fill="#c89a55" stroke="#5a3f24" stroke-width="1"/>
    <!-- Chest (split into chest, ribs L/R) -->
    <!-- Chest (center) -->
    <path d="M55 80 L105 80 L105 120 L55 120 Z" fill="${col.CHEST}" stroke="#ffd700" stroke-width="1.5"/>
    <text x="80" y="103" text-anchor="middle" font-size="9" fill="#000" font-weight="bold">CHEST ${n('CHEST')}</text>
    <!-- LEFT ribs (viewer's left = opponent's right = LEFT_RIBS label) -->
    <path d="M38 80 L55 80 L55 130 L42 132 Z" fill="${col.LEFT_RIBS}" stroke="#ffd700" stroke-width="1.5"/>
    <text x="48" y="106" text-anchor="middle" font-size="6" fill="#000" font-weight="bold">L-RIB</text>
    <text x="48" y="116" text-anchor="middle" font-size="7" fill="#000" font-weight="bold">${n('LEFT_RIBS')}</text>
    <!-- RIGHT ribs (viewer's right) -->
    <path d="M105 80 L122 80 L118 132 L105 130 Z" fill="${col.RIGHT_RIBS}" stroke="#ffd700" stroke-width="1.5"/>
    <text x="113" y="106" text-anchor="middle" font-size="6" fill="#000" font-weight="bold">R-RIB</text>
    <text x="113" y="116" text-anchor="middle" font-size="7" fill="#000" font-weight="bold">${n('RIGHT_RIBS')}</text>
    <!-- Abs -->
    <path d="M55 120 L105 120 L100 165 L60 165 Z" fill="${col.ABS}" stroke="#ffd700" stroke-width="1.5"/>
    <text x="80" y="148" text-anchor="middle" font-size="9" fill="#000" font-weight="bold">ABS ${n('ABS')}</text>
    <!-- Liver (lower right of viewer = opponent's right side = LIVER) -->
    <path d="M100 130 L118 132 L114 168 L100 165 Z" fill="${col.LIVER}" stroke="#ff6a00" stroke-width="2"/>
    <text x="108" y="150" text-anchor="middle" font-size="6" fill="#000" font-weight="bold">LIVER</text>
    <text x="108" y="160" text-anchor="middle" font-size="7" fill="#000" font-weight="bold">${n('LIVER')}</text>
    <!-- Belt -->
    <rect x="55" y="165" width="50" height="10" fill="#ffd700" stroke="#000" stroke-width="0.5"/>
    <!-- Shorts -->
    <path d="M55 175 L105 175 L100 215 L60 215 Z" fill="#552020" stroke="#000" stroke-width="0.5"/>
  </svg>`;
}
function zoneFill(amount){
  amount = amount || 0;
  if (amount > 28) return '#e64545';
  if (amount > 12) return '#f4d35a';
  return '#f6efe2';
}

function generateAdvice(){
  const lines = [];
  const pZones = player.zoneDmg, cZones = cpu.zoneDmg;
  // Player-side advice (priority order: defense red, low stamina, low offense, opp hurt)
  if (pZones.HEAD > 28) lines.push("<b>Hands UP, kid.</b> Your chin is a bullseye out there â€” tighten that guard and quit eating jabs.");
  if (pZones.LIVER > 28 || pZones.ABS > 28) lines.push("<b>Elbows in.</b> He's parking shots on your body. Tuck those elbows and stop dropping the right hand.");
  if (player.lowStaminaTicks > 6) lines.push("<b>Pace yourself.</b> You're loading up on every shot. Stick the jab, breathe, and stay light on the toes.");
  if (player.punchesThrown < 6) lines.push("<b>Let your hands GO.</b> Doubles, triples on the jab â€” make him respect your range.");
  if (cZones.LIVER > 24 || cZones.ABS > 24) lines.push("<b>He's hurt to the body.</b> Dig in â€” shovel hooks, liver shots, finish the job.");
  if (cZones.HEAD > 24) lines.push("<b>You've found his chin.</b> Set up the right hand behind that jab and put him out.");
  if (lines.length === 0) lines.push("<b>Good round.</b> Cleaner footwork next, keep circling left, work behind that jab.");
  // Pick top 2.
  return lines.slice(0, 2);
}

function showInterlude(onContinue){
  const wrap = document.getElementById('interlude');
  document.getElementById('interlude-title').textContent = 'END OF ROUND ' + round;
  const diagrams = document.getElementById('diagrams');
  diagrams.innerHTML = `
    <div class="diag">
      <div class="who">YOU</div>
      ${buildBodySvg(player.zoneDmg)}
      <div style="font-size:11px;color:#cfc8b8">Total: ${Math.round(totalZoneDamage(player.zoneDmg))}</div>
    </div>
    <div class="diag">
      <div class="who">BRUNO</div>
      ${buildBodySvg(cpu.zoneDmg)}
      <div style="font-size:11px;color:#cfc8b8">Total: ${Math.round(totalZoneDamage(cpu.zoneDmg))}</div>
    </div>
  `;
  const adviceEl = document.getElementById('advice');
  adviceEl.innerHTML = '<div style="margin-bottom:6px;font-size:13px;color:#ffd700;letter-spacing:1px">CORNER:</div>' +
    generateAdvice().map(l => '<div>â€¢ ' + l + '</div>').join('');
  wrap.classList.add('active');
  let elapsed = 0;
  const tEl = document.getElementById('interlude-timer');
  const intervalId = setInterval(() => {
    elapsed += 0.25;
    const left = Math.max(0, Math.ceil(6 - elapsed));
    tEl.textContent = 'Auto-advance in ' + left + 's';
    if (elapsed >= 6){
      clearInterval(intervalId);
      finish();
    }
  }, 250);
  function finish(){
    clearInterval(intervalId);
    wrap.classList.remove('active');
    document.getElementById('btn-continue').onclick = null;
    onContinue();
  }
  document.getElementById('btn-continue').onclick = () => finish();
}

function roundEnd(){
  let winner = null;
  if (player.hp <= 0) winner = 'cpu';
  else if (cpu.hp <= 0) winner = 'player';
  else if (player.hp > cpu.hp) winner = 'player';
