function update(dt){
  roundClock -= dt;
  if (agentVsAgent){
    // Both fighters run on independent AI brains â€” no keyboard input.
    updateAgentBrain(player, cpu, 'brawler', dt);
    updateAgentBrain(cpu, player, 'boxer', dt);
  } else {
    tickPlayer(player, dt);
    tickCpu(cpu, dt);
  }
  checkPunchHit(player, cpu);
  checkPunchHit(cpu, player);
  if (player.hp <= 0 || cpu.hp <= 0){
    state = 'roundover';
