    me.agentMoving = true;
    me.agentTimer = 110;
    me.comboCount = 0;
  } else if (dist > 1.5){
    // Close the gap fast, harass with jabs to keep pressure on.
    agentStep(me, opponent, 0.45);
    me.agentMoving = true;
    if (Math.random() < 0.6) startAction(me, 'jab');
    me.agentTimer = 180 + Math.random() * 80;
    me.comboCount = 0;
  } else {
    // IN RANGE AND GUARD IS DOWN â€” unleash a combo burst.
