      startAction(me, pickPunch(style));
      me.agentTimer = 150 + Math.random() * 100;
    } else {
      // Brief recovery after a 4-punch combo, then resume.
      me.comboCount = 0;
      me.agentTimer = 400 + Math.random() * 200;
    }
  }
}

