// Fighters have a physical radius. Every frame we push them apart so they
// can never walk through each other. The instant that separation distance is
// crossed AND no cooldown is active, call the clinch and break them to
// opposite neutral corners.
const BODY_RADIUS = 0.55;
const CLINCH_DIST = BODY_RADIUS * 2; // 1.10 units â€” touching torsos = clinch
if (state === 'fight' && player.hp > 0 && cpu.hp > 0){
  const cdx = player.pos.x - cpu.pos.x;
  const cdz = player.pos.z - cpu.pos.z;
  const cdist = Math.sqrt(cdx*cdx + cdz*cdz);
  if (cdist < CLINCH_DIST){
    // Hard push-apart: resolve overlap instantly so they never phase through
    const overlap = CLINCH_DIST - cdist;
    const nx = cdist < 0.001 ? 1 : cdx / cdist;
    const nz = cdist < 0.001 ? 0 : cdz / cdist;
    player.pos.x += nx * overlap * 0.5;
    player.pos.z += nz * overlap * 0.5;
    cpu.pos.x    -= nx * overlap * 0.5;
    cpu.pos.z    -= nz * overlap * 0.5;
