// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
//  Boxer rig (3D) â€” anatomical joint hierarchy
//  Shoulder: ball-and-socket (3-axis)
//  Elbow: hinge (Z-axis only)
//  Forearm: pivot (Y-axis only = pronation/supination)
//  Wrist: condyloid (X + Z only)
//  Spine: lumbar (pivot at waist) + thoracic (mid-spine twist)
//  Neck: atlanto-axial pivot (Y) + atlanto-occipital nod (Z in this rig)
//  Hip: ball-and-socket per leg; Knee: hinge (Z); Ankle: hinge (Z)
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function createBoxer3D(opts){
  const root = new THREE.Group();
  const skinMat   = new THREE.MeshLambertMaterial({ color: opts.skin });
  const trunkMat  = new THREE.MeshLambertMaterial({ color: opts.trunks });
  const beltMat   = new THREE.MeshLambertMaterial({ color: 0xffd700 });
  const bootMat   = new THREE.MeshLambertMaterial({ color: 0x111111 });
  const gloveMat  = new THREE.MeshLambertMaterial({ color: opts.gloveColor });
  const cuffMat   = new THREE.MeshLambertMaterial({ color: 0xffffff });
  const stripeMat = new THREE.MeshLambertMaterial({ color: 0xffd700 });
  const hairMat   = new THREE.MeshLambertMaterial({ color: 0x1a0d0d });
  const eyeMat    = new THREE.MeshBasicMaterial({ color: 0x000 });
  const detailMat = new THREE.MeshLambertMaterial({ color: 0x6a4a30 });
  const mouthMat  = new THREE.MeshLambertMaterial({ color: 0x4a1a1a });
  const laceMat   = new THREE.MeshLambertMaterial({ color: 0xffffff });

  // â•�â•�â•� LEGS â€” hipGrp (ball-and-socket) â†’ kneeGrp (hinge, Z) â†’ ankleGrp (hinge, Z) â•�â•�â•�
  function buildLeg(side){
    const hipGrp = new THREE.Group();
    hipGrp.position.set(0, 0.92, side * 0.13);
    root.add(hipGrp);

    const thighTrunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.135, 0.32, 12), trunkMat);
    thighTrunk.position.y = -0.15;
    hipGrp.add(thighTrunk);
    const thighSkin = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.115, 0.18, 10), skinMat);
    thighSkin.position.y = -0.40;
    hipGrp.add(thighSkin);
    // Quad muscle blob (scales on knee flex)
    const quadMesh = new THREE.Mesh(new THREE.SphereGeometry(0.10, 8, 6), skinMat);
    quadMesh.scale.set(0.65, 1.5, 0.75);
    quadMesh.position.set(0.03, -0.32, 0);
    hipGrp.add(quadMesh);
    const kneeSphere = new THREE.Mesh(new THREE.SphereGeometry(0.105, 8, 6), skinMat);
    kneeSphere.position.y = -0.51;
    hipGrp.add(kneeSphere);

    // kneeGrp â€” HINGE: Z axis only
    const kneeGrp = new THREE.Group();
    kneeGrp.position.y = -0.51;
    hipGrp.add(kneeGrp);

    // Kneecap (patella) â€” rides on the front of the joint, moves with knee flex
    const kneecap = new THREE.Mesh(
      new THREE.SphereGeometry(0.072, 10, 8),
      new THREE.MeshLambertMaterial({ color: opts.skin })
    );
    kneecap.scale.set(1.0, 0.75, 1.15); // slightly flat oval, wide on Z
    kneecap.position.set(0.08, 0.02, 0); // sits on the anterior (front) face of the joint
    kneeGrp.add(kneecap);

    const calf = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.085, 0.32, 10), skinMat);
    calf.position.y = -0.17;
    kneeGrp.add(calf);
    // Gastrocnemius (calf muscle) â€” scales on plantarflexion
    const calfMesh = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 6), skinMat);
    calfMesh.scale.set(0.75, 1.35, 1.1);
    calfMesh.position.set(-0.03, -0.14, 0);
    kneeGrp.add(calfMesh);

    // ankleGrp â€” HINGE: Z axis only (dorsiflexion / plantarflexion)
    const ankleGrp = new THREE.Group();
    ankleGrp.position.y = -0.33;
    kneeGrp.add(ankleGrp);
    ankleGrp.rotation.z = 0.14; // default slight dorsiflexion = athletic stance

    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.20, 0.12, 0.32), bootMat);
    boot.position.set(0.04, -0.05, 0);
    ankleGrp.add(boot);
    const bootStripe = new THREE.Mesh(new THREE.BoxGeometry(0.21, 0.02, 0.33), beltMat);
    bootStripe.position.set(0.04, -0.01, 0);
    ankleGrp.add(bootStripe);

    return { hipGrp, kneeGrp, ankleGrp, quadMesh, calfMesh };
  }
  const legLData = buildLeg(-1);
  const legRData = buildLeg(+1);
  const legL = legLData;
  const legR = legRData;

  // â•�â•�â•� HIPS / BELT â•�â•�â•�
  const hipsGroup = new THREE.Group();
  hipsGroup.position.y = 0;
  root.add(hipsGroup);
  const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.20, 0.18, 0.10, 14), beltMat);
  belt.position.y = 0.95;
  hipsGroup.add(belt);

  // â•�â•�â•� SPINE â€” lumbar (pivot at waist y=0) â†’ thoracic (pivot at mid-spine y=1.00) â•�â•�â•�
  const lumbar = new THREE.Group();
  lumbar.position.y = 0;
  root.add(lumbar);

  const waist = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.20, 0.44), skinMat);
  waist.position.y = 1.04;
  lumbar.add(waist);
  const rib = new THREE.Mesh(new THREE.BoxGeometry(0.30, 0.06, 0.50), skinMat);
  rib.position.y = 1.14;
  lumbar.add(rib);

  // thoracic â€” rotates at mid-spine for cross/hook spine twist
  const thoracic = new THREE.Group();
  thoracic.position.y = 1.00; // pivot at mid-spine in lumbar space
  lumbar.add(thoracic);

  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.36, 0.55), skinMat);
  chest.position.y = 0.30; // 1.00 + 0.30 = 1.30 in world
  thoracic.add(chest);
  const pecV = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.30, 0.02), detailMat);
  pecV.position.set(0.16, 0.30, 0);
  thoracic.add(pecV);
  const pecH = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.005, 0.36), detailMat);
  pecH.position.set(0.155, 0.16, 0);
  thoracic.add(pecH);
  for (let i = 0; i < 3; i++){
    const ab = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.005, 0.18), detailMat);
    ab.position.set(0.135, 0.10 - i * 0.05, 0);
    thoracic.add(ab);
  }

  // â•�â•�â•� NECK â€” cylinder mesh + pivot groups for atlanto-axial (Y) and atlanto-occipital (Z) â•�â•�â•�
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.085, 0.12, 10), skinMat);
  neck.position.y = 0.55; // 1.00 + 0.55 = 1.55 in world
  thoracic.add(neck);

  // neckPivot: atlanto-axial joint â€” Y axis only (head rotation left/right)
  const neckPivot = new THREE.Group();
  neckPivot.position.y = 0.62; // 1.00 + 0.62 = 1.62 in world
  thoracic.add(neckPivot);

  // neckNod: atlanto-occipital joint â€” Z axis = nod (forward/back) in this rig
  const neckNod = new THREE.Group();
